window.QUIZ_BANK['junit'] = (window.QUIZ_BANK['junit']||[]).concat([
{id:4811,topic:'junit',difficulty:'beginner',question:'Which module in JUnit 5 provides the new programming model for writing tests?',options:['JUnit Vintage','JUnit Platform','JUnit Jupiter','JUnit Classic'],answer:2,explanation:'JUnit Jupiter is the JUnit 5 module that provides the new annotation-based programming model and extension model for writing tests. The Platform is the launcher, and Vintage supports JUnit 3/4 tests.'},
{id:4812,topic:'junit',difficulty:'beginner',question:'What is the role of the JUnit Platform module?',options:['Provides backward compatibility for JUnit 3/4','Provides the new @Test annotation','Serves as the foundation for launching testing frameworks on the JVM','Integrates with Mockito'],answer:2,explanation:'JUnit Platform is the foundation that enables discovering and launching tests on the JVM. It defines the TestEngine API that all test frameworks (Jupiter, Vintage, third-party) implement to participate in test execution.'},
{id:4813,topic:'junit',difficulty:'beginner',question:'Which JUnit 5 module allows running legacy JUnit 4 tests alongside JUnit 5 tests?',options:['JUnit Jupiter','JUnit Platform','JUnit Vintage','JUnit Legacy'],answer:2,explanation:'JUnit Vintage provides a TestEngine that allows running JUnit 3 and JUnit 4 tests on the JUnit Platform, giving teams a migration path while running both old and new tests in the same build.'},
{id:4814,topic:'junit',difficulty:'beginner',question:'What is the minimum access modifier required for a JUnit 5 @Test method?',options:['public','protected','package-private (no modifier)','private'],answer:2,explanation:'JUnit 5 relaxed the requirement from JUnit 4: test methods no longer need to be public. Package-private (default) access is sufficient. Private methods are not supported and will not be recognized as tests.'},
{id:4815,topic:'junit',difficulty:'beginner',question:'Which annotation marks a method to run before each test method in a JUnit 5 class?',options:['@Before','@Setup','@BeforeEach','@BeforeTest'],answer:2,explanation:'@BeforeEach replaces JUnit 4\'s @Before annotation. The annotated method runs before every single @Test, @ParameterizedTest, or @RepeatedTest method in the class, making it ideal for resetting shared state.'},
{id:4816,topic:'junit',difficulty:'beginner',question:'Which annotation marks a method to run once before all tests in a JUnit 5 class?',options:['@BeforeClass','@BeforeAll','@BeforeEach','@SetupAll'],answer:1,explanation:'@BeforeAll replaces JUnit 4\'s @BeforeClass annotation. By default the method must be static. When @TestInstance(Lifecycle.PER_CLASS) is used, it can be an instance method. It runs exactly once before any test in the class.'},
{id:4817,topic:'junit',difficulty:'beginner',question:'What does the @Disabled annotation do in JUnit 5?',options:['Marks a test class or method to be skipped','Marks a test as expected to fail','Reduces test priority','Runs the test but ignores its result'],answer:0,explanation:'@Disabled is the JUnit 5 equivalent of JUnit 4\'s @Ignore. When placed on a class or method, JUnit skips it entirely during test execution. A reason string can be provided as a value for documentation purposes.'},
{id:4818,topic:'junit',difficulty:'beginner',question:'Which annotation provides a custom display name for a test class or method in JUnit 5?',options:['@Name','@Label','@DisplayName','@Title'],answer:2,explanation:'@DisplayName lets you assign human-readable names—including spaces, special characters, and emoji—to test classes and methods. These names appear in IDEs and test reports, making output more descriptive than method names.'},
{id:4819,topic:'junit',difficulty:'intermediate',question:'What does @AfterEach do in JUnit 5?',options:['Runs once after all tests complete','Runs after each individual test method','Runs only after failed tests','Runs after the entire test suite'],answer:1,explanation:'@AfterEach replaces JUnit 4\'s @After annotation. The annotated method runs after every individual test method, including @ParameterizedTest and @RepeatedTest invocations. It is used for cleanup like closing resources opened in @BeforeEach.'},
{id:4820,topic:'junit',difficulty:'intermediate',question:'Which lifecycle annotation in JUnit 5 replaces @AfterClass from JUnit 4?',options:['@AfterAll','@AfterEach','@TeardownAll','@FinalCleanup'],answer:0,explanation:'@AfterAll replaces JUnit 4\'s @AfterClass. It must be static by default (or non-static when using @TestInstance(Lifecycle.PER_CLASS)) and runs exactly once after all tests in the class have been executed.'},
{id:4821,topic:'junit',difficulty:'intermediate',question:'What is the default test instance lifecycle in JUnit 5?',options:['Lifecycle.PER_CLASS','Lifecycle.PER_METHOD','Lifecycle.PER_SUITE','Lifecycle.SHARED'],answer:1,explanation:'By default, JUnit 5 creates a new test class instance for each test method (PER_METHOD), which mirrors JUnit 4 behavior. This ensures test isolation by preventing state leakage between test methods through instance fields.'},
{id:4822,topic:'junit',difficulty:'intermediate',question:'What behavior change does @TestInstance(Lifecycle.PER_CLASS) enable?',options:['A new instance is created for each test','A single instance is shared across all tests in the class','Tests run in parallel automatically','@BeforeAll must be static'],answer:1,explanation:'With Lifecycle.PER_CLASS, JUnit creates one test class instance shared by all test methods. This allows @BeforeAll and @AfterAll methods to be non-static. It also enables stateful tests, though shared mutable state must be managed carefully.'},
{id:4823,topic:'junit',difficulty:'intermediate',question:'What does the @Tag annotation provide in JUnit 5?',options:['Assigns a priority to a test','Groups tests with a label for selective filtering','Marks tests as integration tests only','Replaces @Category from JUnit 4 with different semantics'],answer:1,explanation:'@Tag allows you to assign one or more string tags to test classes or methods. The build tool or test runner can then include or exclude tests based on these tags, enabling selective test execution like running only "fast" or "smoke" tests.'},
{id:4824,topic:'junit',difficulty:'intermediate',question:'Which JUnit 5 assertion checks that two values are equal?',options:['assertSame','assertEqualTo','assertEquals','assertMatch'],answer:2,explanation:'assertEquals(expected, actual) checks that two values are equal using the equals() method. JUnit 5\'s version places the expected value first and actual second. An optional third argument can provide a failure message or message supplier.'},
{id:4825,topic:'junit',difficulty:'beginner',question:'Which assertion verifies that a condition is true in JUnit 5?',options:['assertCorrect','assertTrue','assertPositive','assertValid'],answer:1,explanation:'assertTrue(condition) asserts that the supplied boolean condition is true. It can also accept a BooleanSupplier. An optional message argument (String or Supplier<String>) can be provided for a descriptive failure message.'},
{id:4826,topic:'junit',difficulty:'beginner',question:'Which JUnit 5 assertion verifies that a reference is null?',options:['assertEmpty','assertNull','assertVoid','assertNone'],answer:1,explanation:'assertNull(object) asserts that the supplied object reference is null. If it is not null, the test fails. An optional failure message can be supplied as a second argument to provide context when the assertion fails.'},
{id:4827,topic:'junit',difficulty:'beginner',question:'Which JUnit 5 assertion verifies that a reference is NOT null?',options:['assertExists','assertNotNull','assertPresent','assertDefined'],answer:1,explanation:'assertNotNull(object) asserts that the supplied object reference is not null. If it is null, the test fails. Like other assertions, it accepts an optional String or Supplier<String> as a message argument.'},
{id:4828,topic:'junit',difficulty:'intermediate',question:'What does assertThrows() return in JUnit 5?',options:['void','A boolean','The thrown exception instance','The exception message'],answer:2,explanation:'assertThrows(expectedType, executable) asserts that executing the given code throws an exception of the expected type and returns the exception instance. This allows you to make further assertions on the exception, such as checking its message.'},
{id:4829,topic:'junit',difficulty:'intermediate',question:'What is the purpose of assertDoesNotThrow() in JUnit 5?',options:['Verifies an exception is thrown and ignored','Asserts that the executable does not throw any exception','Replaces try-catch blocks for expected exceptions','Marks an exception as acceptable'],answer:1,explanation:'assertDoesNotThrow(executable) asserts that the given ThrowingSupplier or Executable does not throw any exception. It is useful for making explicit that no exception is expected, making test intent clearer than a plain method call.'},
{id:4830,topic:'junit',difficulty:'intermediate',question:'What is the main benefit of assertAll() in JUnit 5?',options:['It runs assertions in parallel','It groups multiple assertions so all are evaluated even if one fails','It only checks the first failed assertion','It replaces assertEquals for collections'],answer:1,explanation:'assertAll(executables...) groups multiple assertions and executes all of them, collecting all failures and reporting them together. Unlike individual assertions that abort on first failure, assertAll provides a complete picture of which assertions passed and failed.'},
{id:4831,topic:'junit',difficulty:'intermediate',question:'What does assertTimeout(duration, executable) do when the timeout is exceeded?',options:['Kills the JVM','Marks the test as skipped','Fails the test after the executable finishes but does not abort it','Prints a warning but passes the test'],answer:2,explanation:'assertTimeout waits for the executable to complete and only then checks whether it exceeded the duration. This means the executable runs to completion even if it exceeds the timeout, making it different from assertTimeoutPreemptively.'},
{id:4832,topic:'junit',difficulty:'advanced',question:'How does assertTimeoutPreemptively() differ from assertTimeout() in JUnit 5?',options:['assertTimeoutPreemptively has no timeout limit','assertTimeoutPreemptively runs the executable in a separate thread and aborts if the timeout is exceeded','assertTimeout runs in a separate thread','There is no difference; they are aliases'],answer:1,explanation:'assertTimeoutPreemptively executes the code in a separate thread and forcibly fails the test if the timeout is exceeded before the executable finishes. This prevents long-running tests from blocking the suite, unlike assertTimeout which always waits for completion.'},
{id:4833,topic:'junit',difficulty:'intermediate',question:'What is the purpose of assumeTrue() in JUnit 5?',options:['Asserts that a condition is true; fails if false','Skips the remainder of the test if the condition is false','Marks a test as expected to pass','Conditionally enables a test class'],answer:1,explanation:'assumeTrue(condition) is an assumption, not an assertion. If the condition is false, the test is aborted (marked as skipped/aborted, not failed). This is useful for skipping tests when preconditions like environment variables or OS type are not met.'},
{id:4834,topic:'junit',difficulty:'intermediate',question:'What does assumingThat(condition, executable) do when the condition is false?',options:['Fails the test','Runs the executable anyway','Skips only the executable block but continues the rest of the test','Throws an AssumptionViolatedException'],answer:2,explanation:'assumingThat executes the given executable only if the condition is true. If false, the executable is skipped but the test continues executing beyond it. This is more granular than assumeTrue, which aborts the entire test.'},
{id:4835,topic:'junit',difficulty:'intermediate',question:'Which annotation is used to run the same test with multiple values in JUnit 5?',options:['@RepeatedTest','@MultiTest','@ParameterizedTest','@DataDrivenTest'],answer:2,explanation:'@ParameterizedTest marks a method to be run multiple times with different arguments. It requires a source annotation like @ValueSource, @CsvSource, or @MethodSource to supply the arguments for each invocation.'},
{id:4836,topic:'junit',difficulty:'intermediate',question:'Which source annotation supplies a single array of literal values to a @ParameterizedTest?',options:['@CsvSource','@ValueSource','@LiteralSource','@ArraySource'],answer:1,explanation:'@ValueSource provides a single array of values (strings, ints, longs, doubles, chars, booleans, shorts, bytes, floats, or classes). Each element becomes the argument for one test invocation, making it ideal for single-argument parameterized tests.'},
{id:4837,topic:'junit',difficulty:'intermediate',question:'What format does @CsvSource use to supply multiple arguments to a @ParameterizedTest?',options:['JSON arrays','XML elements','Comma-separated value strings, one per test invocation','Properties file format'],answer:2,explanation:'@CsvSource accepts an array of comma-separated strings. Each string represents one test invocation with multiple arguments. For example, {"apple, 1", "banana, 2"} would call the test method twice with (apple,1) and (banana,2).'},
{id:4838,topic:'junit',difficulty:'intermediate',question:'What does @CsvFileSource do in a @ParameterizedTest?',options:['Reads CSV data from a system property','Loads test arguments from an external CSV file on the classpath','Generates CSV output from test results','Maps CSV columns to Java bean properties'],answer:1,explanation:'@CsvFileSource points to one or more CSV files on the classpath. Each data row in the file becomes a set of arguments for one test invocation. The numLinesToSkip attribute can be used to skip header rows.'},
{id:4839,topic:'junit',difficulty:'intermediate',question:'What must a @MethodSource method return to supply arguments to a @ParameterizedTest?',options:['A List<Object>','A Stream, Iterable, Iterator, or array of arguments','A CSV string','A @ValueSource annotation'],answer:1,explanation:'A @MethodSource factory method must return a Stream<Arguments>, Stream of primitives/strings, Collection, Iterator, or array. By default, the method name matches the test method name and must be static (unless PER_CLASS lifecycle is used).'},
{id:4840,topic:'junit',difficulty:'intermediate',question:'What does @EnumSource supply to a @ParameterizedTest?',options:['A stream of strings','All or selected constants of an enum type','Random enum-like values','An annotation-based enum definition'],answer:1,explanation:'@EnumSource provides enum constants as test arguments. By default it uses all constants of the specified enum. The names attribute with a mode (INCLUDE, EXCLUDE, MATCH_ALL, MATCH_ANY) lets you select a subset of constants.'},
{id:4841,topic:'junit',difficulty:'intermediate',question:'What does @NullSource add to a @ParameterizedTest?',options:['A test that expects a NullPointerException','A single null argument as one extra invocation','Empty string argument','Disables null checking'],answer:1,explanation:'@NullSource adds a single invocation with a null argument to the parameterized test. It can be combined with @EmptySource and @ValueSource to test null, empty, and other values in the same test method.'},
{id:4842,topic:'junit',difficulty:'intermediate',question:'What does @EmptySource provide to a @ParameterizedTest method?',options:['An invocation with an empty string, collection, or array depending on parameter type','A test that verifies empty state','A null argument','A skip signal'],answer:0,explanation:'@EmptySource adds an invocation with an empty value appropriate to the parameter type: empty String for String, empty list/set/map for collection types, empty array for arrays. It is often combined with @NullSource via the combined @NullAndEmptySource.'},
{id:4843,topic:'junit',difficulty:'advanced',question:'What interface must a custom @ArgumentsSource implement in JUnit 5?',options:['ArgumentFactory','ArgumentProvider','ArgumentsProvider','ParameterSource'],answer:2,explanation:'To create a custom argument source, implement the org.junit.jupiter.params.provider.ArgumentsProvider interface, which defines provideArguments(ExtensionContext context) returning a Stream<? extends Arguments>. Register it with @ArgumentsSource(MyProvider.class).'},
{id:4844,topic:'junit',difficulty:'intermediate',question:'What does the @TempDir annotation inject in JUnit 5?',options:['A mock file system','A temporary directory that is created before the test and deleted afterwards','A reference to the system temp directory','A fixed test resources directory'],answer:1,explanation:'@TempDir can be injected as a field or parameter of type java.io.File or java.nio.file.Path. JUnit creates the directory before the test and attempts to delete it (and all contents) after the test completes, ensuring a clean filesystem state.'},
{id:4845,topic:'junit',difficulty:'intermediate',question:'What does @RepeatedTest(5) do in JUnit 5?',options:['Runs the test 5 times and expects all to pass','Runs the test 5 times and passes if at least one succeeds','Runs the test once but retries up to 5 times on failure','Marks the test as flaky'],answer:0,explanation:'@RepeatedTest(n) runs the test method exactly n times. Each repetition is treated as a separate test invocation. The display name can reference {currentRepetition} and {totalRepetitions} placeholders. All repetitions must pass for the overall test to pass.'},
{id:4846,topic:'junit',difficulty:'intermediate',question:'What is the primary purpose of @Nested classes in JUnit 5?',options:['To run tests in parallel','To group related tests hierarchically with shared setup and context','To isolate tests in separate classloaders','To enable test inheritance'],answer:1,explanation:'@Nested test classes organize related tests into hierarchical groups within a single test class. Inner classes can have their own @BeforeEach/@AfterEach methods that complement the outer class setup. Non-static inner classes are required for @Nested.'},
{id:4847,topic:'junit',difficulty:'intermediate',question:'Can @BeforeAll be used in a @Nested inner class with the default lifecycle?',options:['Yes, always','No, because @Nested classes are non-static inner classes and @BeforeAll requires a static method by default','Yes, if the method is static','Only if @Disabled is removed'],answer:1,explanation:'@Nested classes are non-static inner classes. With the default PER_METHOD lifecycle, @BeforeAll must be static. Since inner classes cannot have static methods in Java (pre-Java 16), @BeforeAll in @Nested requires @TestInstance(Lifecycle.PER_CLASS) on the inner class.'},
{id:4848,topic:'junit',difficulty:'intermediate',question:'Which @TestMethodOrder strategy orders tests by the @Order annotation value?',options:['MethodOrderer.DisplayName','MethodOrderer.Alphanumeric','MethodOrderer.OrderAnnotation','MethodOrderer.Random'],answer:2,explanation:'MethodOrderer.OrderAnnotation sorts test methods by the numeric value provided in the @Order annotation. Lower values execute first. Methods without @Order are assigned a default order value and run after explicitly ordered methods.'},
{id:4849,topic:'junit',difficulty:'intermediate',question:'Which @TestMethodOrder strategy randomizes test execution order?',options:['MethodOrderer.Random','MethodOrderer.Shuffle','MethodOrderer.Chaos','MethodOrderer.Unpredictable'],answer:0,explanation:'MethodOrderer.Random shuffles test methods into a random order before each execution. A seed can be configured via the junit.jupiter.execution.order.random.seed configuration parameter to make the random order reproducible.'},
{id:4850,topic:'junit',difficulty:'intermediate',question:'Which @TestMethodOrder strategy orders tests alphabetically by display name?',options:['MethodOrderer.Alphanumeric','MethodOrderer.DisplayName','MethodOrderer.NameOrder','MethodOrderer.Alphabetical'],answer:1,explanation:'MethodOrderer.DisplayName orders test methods alphanumerically based on their display names (set via @DisplayName or defaulting to the method name). MethodOrderer.Alphanumeric (deprecated in 5.7) ordered by method name and parameter types.'},
{id:4851,topic:'junit',difficulty:'advanced',question:'In JUnit 5, what is the correct import for the Assertions class?',options:['org.junit.Assert','org.junit.jupiter.api.Assertions','org.junit.platform.Assertions','junit.framework.Assert'],answer:1,explanation:'JUnit 5 assertions are in org.junit.jupiter.api.Assertions. The old org.junit.Assert from JUnit 4 still works via JUnit Vintage, but new JUnit 5 tests should use the Jupiter Assertions class, which supports lambdas for lazy message evaluation.'},
{id:4852,topic:'junit',difficulty:'intermediate',question:'What happens when an assertAll() group has multiple failing assertions?',options:['Only the first failure is reported','All failures are collected and reported together in a MultipleFailuresError','The test passes if at least one assertion passes','Each failure throws a separate exception'],answer:1,explanation:'assertAll collects all assertion failures from all provided executables and throws a MultipleFailuresError that lists every failed assertion. This lets you see the complete failure state in one test run rather than fixing one assertion at a time.'},
{id:4853,topic:'junit',difficulty:'intermediate',question:'What is the difference between assertSame() and assertEquals() in JUnit 5?',options:['assertSame uses equals(); assertEquals uses ==','assertSame uses ==; assertEquals uses equals()','They are identical','assertSame is deprecated'],answer:1,explanation:'assertSame(expected, actual) uses the == operator to verify that both references point to the exact same object instance. assertEquals(expected, actual) uses the equals() method to verify logical equality, allowing different instances with the same value to pass.'},
{id:4854,topic:'junit',difficulty:'intermediate',question:'In a @ParameterizedTest with @CsvSource, how do you represent a null value in a CSV string?',options:['Use the literal text "null" (case-insensitive)','Leave the field blank between commas','Use the string "NULL" only','It is not possible'],answer:0,explanation:'By default, an empty string in @CsvSource is treated as an empty string, but you can configure nullValues attribute to treat specific strings (like "null" or "NIL") as null. Since JUnit 5.6, the empty string defaults to empty, not null, unless nullValues is set.'},
{id:4855,topic:'junit',difficulty:'intermediate',question:'Which annotation controls the order in which test methods run when using MethodOrderer.OrderAnnotation?',options:['@Priority','@Rank','@Order','@Sequence'],answer:2,explanation:'@Order(n) from org.junit.jupiter.api annotation provides the integer ordering value used by MethodOrderer.OrderAnnotation. Lower values have higher priority. The same annotation is used for extension ordering via @RegisterExtension.'},
{id:4856,topic:'junit',difficulty:'intermediate',question:'What is the purpose of the RepetitionInfo parameter in @RepeatedTest?',options:['It sets the number of repetitions','It provides current repetition index and total count within the test method','It controls whether the test is repeated on failure','It maps to a @ValueSource element'],answer:1,explanation:'A @RepeatedTest method can accept a RepetitionInfo parameter injected by JUnit. It provides getCurrentRepetition() and getTotalRepetitions() methods, allowing the test body to behave differently based on which repetition is currently executing.'},
{id:4857,topic:'junit',difficulty:'advanced',question:'What is the significance of the @TestMethodOrder annotation being placed on the class vs inherited?',options:['Inherited placement disables ordering','Class-level placement applies to all methods in that class; it is not inherited by subclasses by default','It makes no difference','Inherited placement causes random ordering'],answer:1,explanation:'@TestMethodOrder is a class-level annotation and is not inherited by subclasses. Each subclass must declare its own @TestMethodOrder if ordering is desired. This is consistent with JUnit 5\'s general approach of non-inherited test annotations.'},
{id:4858,topic:'junit',difficulty:'intermediate',question:'Which assertion in JUnit 5 specifically checks that two object references are NOT the same instance?',options:['assertNotEquals','assertNotSame','assertDifferent','assertDistinct'],answer:1,explanation:'assertNotSame(unexpected, actual) uses the == operator and fails if both references point to the same object. It is the counterpart of assertSame and checks object identity (not equality), ensuring two different objects are returned rather than the same cached instance.'},
{id:4859,topic:'junit',difficulty:'beginner',question:'Which JUnit 5 annotation is the direct equivalent of @Ignore in JUnit 4?',options:['@Skip','@Disabled','@Exclude','@Inactive'],answer:1,explanation:'@Disabled is the JUnit 5 replacement for @Ignore from JUnit 4. It can be applied to both test classes and test methods. The annotation accepts an optional string parameter to document why the test is disabled.'},
{id:4860,topic:'junit',difficulty:'intermediate',question:'How many parameters can @ValueSource supply per test invocation?',options:['As many as needed','Exactly one','Two','Up to four'],answer:1,explanation:'@ValueSource is designed to supply exactly one argument per invocation. Each element in the values array becomes a single argument for one invocation. For multiple arguments per invocation, use @CsvSource, @MethodSource, or @ArgumentsSource instead.'},
{id:4861,topic:'junit',difficulty:'intermediate',question:'What does the @NullAndEmptySource annotation combine?',options:['@NullSource and @CsvSource','@NullSource and @EmptySource','@EmptySource and @ValueSource with null','@NullSource and @BlankSource'],answer:1,explanation:'@NullAndEmptySource is a composed annotation that combines @NullSource and @EmptySource. It adds two extra invocations: one with null and one with an empty value. It is a convenience shorthand for applying both annotations together.'},
{id:4862,topic:'junit',difficulty:'advanced',question:'What is a composed annotation in JUnit 5?',options:['An annotation that extends another annotation','A meta-annotation pattern where one annotation is annotated with JUnit annotations to combine their behavior','Two annotations applied side by side','An annotation that contains a class reference'],answer:1,explanation:'JUnit 5 supports composed annotations (meta-annotations) where you create a custom annotation and annotate it with one or more JUnit annotations. For example, you can create @FastTest that combines @Test and @Tag("fast"), applying both effects with a single annotation.'},
{id:4863,topic:'junit',difficulty:'intermediate',question:'What type must a @MethodSource factory method be by default in JUnit 5?',options:['An instance method of the test class','A static method','A method in an external class','A lambda expression'],answer:1,explanation:'By default, a @MethodSource factory method must be static, similar to @BeforeAll. The exception is when @TestInstance(Lifecycle.PER_CLASS) is used, in which case the factory method can be a non-static instance method of the test class.'},
{id:4864,topic:'junit',difficulty:'intermediate',question:'In JUnit 5, which class do you extend to create custom arguments for @MethodSource?',options:['Arguments.of() static factory method','ArgumentsFactory','ParameterProvider','ArgumentsResolver'],answer:0,explanation:'You don\'t extend a class; instead you use the Arguments.of(Object... args) static factory method from org.junit.jupiter.params.provider.Arguments to create argument sets. A @MethodSource method returns a Stream<Arguments> where each element is Arguments.of(...).'},
{id:4865,topic:'junit',difficulty:'intermediate',question:'What is the default name format for a @RepeatedTest display name?',options:['"repetition N of total"','The method name followed by the count','The test class name plus index','Custom only'],answer:0,explanation:'The default display name for each @RepeatedTest invocation is "repetition {currentRepetition} of {totalRepetitions}". This can be customized by providing a name attribute to @RepeatedTest using the {displayName}, {currentRepetition}, and {totalRepetitions} placeholders.'},
{id:4866,topic:'junit',difficulty:'intermediate',question:'Which JUnit 5 assertion method verifies that an array or list has a specific length or size?',options:['assertSize','assertLength','There is no built-in assertion; use assertEquals on the size/length directly','assertCount'],answer:2,explanation:'JUnit 5 does not have dedicated assertSize or assertLength methods. You compare sizes directly: assertEquals(3, list.size()) or assertEquals(3, array.length). Libraries like AssertJ provide richer collection assertions if needed.'},
{id:4867,topic:'junit',difficulty:'advanced',question:'What happens if a @BeforeAll method throws an exception in JUnit 5?',options:['Only the first test fails','All tests in the class are marked as failed','All tests in the class are skipped/aborted','JUnit retries the @BeforeAll method'],answer:1,explanation:'If a @BeforeAll method throws an exception, JUnit marks all tests in the class as failed (not skipped). This is because the setup required for those tests could not be completed, so their results are considered invalid.'},
{id:4868,topic:'junit',difficulty:'intermediate',question:'Can @Tag annotations be applied to both classes and methods in JUnit 5?',options:['Only to methods','Only to classes','To both classes and methods','Only to classes when using @TestSuite'],answer:2,explanation:'@Tag can be applied to test classes and test methods. Tags applied to a class are inherited by all test methods in that class. Multiple @Tag annotations can be applied to a single element using repeated annotation support in Java 8+.'},
{id:4869,topic:'junit',difficulty:'intermediate',question:'What does assertFalse() verify in JUnit 5?',options:['That a condition is false','That an object is null','That a collection is empty','That a method does not throw'],answer:0,explanation:'assertFalse(condition) asserts that the supplied boolean condition is false. If the condition is true, the test fails. Like assertTrue, it accepts a BooleanSupplier or a direct boolean, plus an optional message argument.'},
{id:4870,topic:'junit',difficulty:'intermediate',question:'In a nested @Nested test structure, which @BeforeEach methods run before an inner test?',options:['Only the outer class @BeforeEach','Only the inner class @BeforeEach','Both outer and inner @BeforeEach methods, outer running first','None; lifecycle methods don\'t work in @Nested'],answer:2,explanation:'When using @Nested classes, the @BeforeEach methods of the enclosing (outer) class run first, then the @BeforeEach methods of the inner class. This creates a natural setup hierarchy matching the nested structure.'},
{id:4871,topic:'junit',difficulty:'advanced',question:'What is the effect of using @TestInstance(Lifecycle.PER_CLASS) on @BeforeAll in a @Nested class?',options:['@BeforeAll is ignored','@BeforeAll can be a non-static instance method in the nested class','@BeforeAll must still be static','The outer class lifecycle is applied instead'],answer:1,explanation:'When @TestInstance(Lifecycle.PER_CLASS) is applied to a @Nested class, @BeforeAll and @AfterAll methods in that nested class can be non-static. Since @Nested classes are inner classes (cannot have static members by default), this is the required approach.'},
{id:4872,topic:'junit',difficulty:'intermediate',question:'Which method in JUnit 5 Assertions throws an AssertionError with a custom message?',options:['fail(message)','error(message)','abort(message)','raise(message)'],answer:0,explanation:'Assertions.fail(message) unconditionally throws an AssertionError with the supplied message. It can also accept a Throwable as a cause. It is useful in test branches where reaching certain code should always fail the test.'},
{id:4873,topic:'junit',difficulty:'intermediate',question:'What is the purpose of providing a Supplier<String> instead of a String as the message argument to an assertion?',options:['It makes the assertion asynchronous','The message is only evaluated (and thus the string built) if the assertion fails, improving performance','It allows parameterized messages','It is required for assertions in lambda expressions'],answer:1,explanation:'Using a Supplier<String> for the failure message means the message string is computed lazily—only if the assertion actually fails. This avoids the performance cost of string construction (e.g., string concatenation in a loop) when assertions succeed.'},
{id:4874,topic:'junit',difficulty:'intermediate',question:'What does the @TempDir annotation do at the class (field) level versus the parameter level?',options:['Field injection shares the directory across all tests; parameter injection creates a new directory per test','They behave identically','Field injection creates a new directory per test; parameter injection is not supported','Parameter injection is only for @BeforeEach'],answer:0,explanation:'A @TempDir static field (or shared field with PER_CLASS) creates one directory shared by all tests. A @TempDir instance field creates a new directory per test instance. A @TempDir method parameter creates a new directory for that specific test method invocation.'},
{id:4875,topic:'junit',difficulty:'advanced',question:'Which JUnit 5 class is used to programmatically discover and run tests without a build tool?',options:['TestRunner','JUnitPlatform','Launcher','TestExecutor'],answer:2,explanation:'The Launcher API (org.junit.platform.launcher.Launcher) allows programmatic test discovery and execution. You create a LauncherDiscoveryRequest specifying selectors and filters, then pass it to a Launcher obtained from LauncherFactory.create().'},
{id:4876,topic:'junit',difficulty:'intermediate',question:'What happens when you use @ParameterizedTest without a source annotation?',options:['All public methods are used as sources','JUnit uses @ValueSource by default','JUnit throws a configuration exception at runtime','The test is run once with no arguments'],answer:2,explanation:'A @ParameterizedTest must have at least one arguments source annotation (@ValueSource, @CsvSource, etc.) or JUnit will throw a PreconditionViolationException when attempting to discover or run the test, because no argument provider is available.'},
{id:4877,topic:'junit',difficulty:'intermediate',question:'In JUnit 5, which Assumptions method accepts a condition and an executable to run only when the condition holds?',options:['assumeTrue(condition, executable)','assumeOnlyIf(condition, executable)','assumingThat(condition, executable)','conditionalTest(condition, executable)'],answer:2,explanation:'assumingThat(boolean assumption, Executable executable) runs the executable only when the assumption is true. Unlike assumeTrue, if the assumption is false, only the executable is skipped and the test continues, allowing partial conditional execution within a single test.'},
{id:4878,topic:'junit',difficulty:'beginner',question:'What package contains the @Test annotation in JUnit 5?',options:['org.junit','junit.framework','org.junit.jupiter.api','org.junit.platform.api'],answer:2,explanation:'In JUnit 5, the @Test annotation is located in org.junit.jupiter.api package, not org.junit like in JUnit 4. When migrating, updating the import statement is necessary. The method signature no longer requires public access modifier.'},
{id:4879,topic:'junit',difficulty:'intermediate',question:'How do you specify a custom display name for each invocation of a @ParameterizedTest?',options:['Use @DisplayName on the method','Set the name attribute of @ParameterizedTest with placeholders like {index} or {arguments}','Use @RepeatedTest with a name','It is not possible to customize parameterized test names'],answer:1,explanation:'The name attribute of @ParameterizedTest accepts a pattern string with placeholders: {index} for the invocation index, {arguments} for all arguments, {0}, {1}, etc. for individual arguments, and {displayName} for the test method\'s display name.'},
{id:4880,topic:'junit',difficulty:'advanced',question:'What is the difference between @Tag filtering at the test class level and at the method level in terms of inheritance?',options:['Method-level tags are inherited by subclasses; class-level are not','Class-level @Tag annotations are not inherited by subclasses; method-level tags apply only to their method','Both are inherited','Neither is inherited'],answer:1,explanation:'@Tag annotations at the class level are not inherited by subclasses—each class must declare its own tags. Method-level @Tag annotations apply only to that specific method. To filter all tests in a subclass, re-apply @Tag to the subclass as well.'},
{id:4881,topic:'junit',difficulty:'intermediate',question:'Which JUnit 5 annotation replaces the concept of @Rule from JUnit 4?',options:['@Extension','@ExtendWith','@Rule still works in JUnit 5','@RegisterExtension'],answer:1,explanation:'JUnit 4\'s @Rule mechanism is replaced by the Extension API in JUnit 5. @ExtendWith(SomeExtension.class) registers extensions declaratively, while @RegisterExtension supports programmatic registration. JUnit Vintage can run @Rule-based tests for compatibility.'},
{id:4882,topic:'junit',difficulty:'intermediate',question:'What is the correct way to assert that a specific exception message is thrown in JUnit 5?',options:['assertThrows with message matching built-in','Catch the result of assertThrows and call getMessage() then use assertEquals','Use @ExpectedException annotation','Use assumeThrows'],answer:1,explanation:'assertThrows returns the thrown exception instance. You then call assertion methods on it: MyException ex = assertThrows(MyException.class, () -> code()); assertEquals("expected message", ex.getMessage()); This two-step approach replaces JUnit 4\'s @Test(expected=...).'},
{id:4883,topic:'junit',difficulty:'advanced',question:'Can a @ParameterizedTest method accept a TestInfo parameter alongside its argument?',options:['No, only the argument parameter is allowed','Yes, JUnit injects additional parameters like TestInfo and TestReporter after the arguments','Only before the argument parameter','Only if @TestInfo annotation is added'],answer:1,explanation:'@ParameterizedTest methods can accept extra parameters beyond the declared arguments, as long as they are resolved by registered ParameterResolvers. TestInfo and TestReporter parameters are auto-resolved by built-in resolvers and are appended after the explicit arguments.'},
{id:4884,topic:'junit',difficulty:'intermediate',question:'What is the default behavior of JUnit 5 when a @BeforeEach method fails?',options:['The test still runs','The test is skipped','The test is marked as failed','JUnit retries the setup'],answer:2,explanation:'If a @BeforeEach method throws an exception, the corresponding test method is not executed and is marked as failed (not skipped). The @AfterEach method still runs (if present) to perform any necessary cleanup even after a setup failure.'},
{id:4885,topic:'junit',difficulty:'intermediate',question:'Which JUnit 5 annotation would you use to prevent a test from executing without permanently removing it?',options:['@Ignored','@Disabled','@Pending','@Skip'],answer:1,explanation:'@Disabled is used to temporarily skip a test without deleting it. The annotation accepts an optional reason string, e.g., @Disabled("Waiting for bug #123 to be fixed"), providing context in test reports about why the test is not running.'},
{id:4886,topic:'junit',difficulty:'advanced',question:'What is the JUnit 5 requirement for @AfterAll methods regarding exceptions?',options:['They must not throw checked exceptions','They should swallow all exceptions','They can throw any exception; all @AfterAll methods run regardless of exceptions in others','If one @AfterAll throws, subsequent @AfterAll methods are skipped'],answer:2,explanation:'JUnit 5 guarantees that all @AfterAll methods are invoked even if one throws an exception. All exceptions are collected and reported together. This ensures complete cleanup even in the presence of errors, similar to how assertAll collects assertion failures.'},
{id:4887,topic:'junit',difficulty:'intermediate',question:'What type does a @ValueSource ints attribute accept?',options:['Integer[]','int[]','List<Integer>','String[] with parseable integers'],answer:1,explanation:'The ints attribute of @ValueSource accepts a primitive int array: @ValueSource(ints = {1, 2, 3}). JUnit 5 supports primitive arrays for all numeric types (bytes, shorts, ints, longs, floats, doubles) as well as chars, booleans, strings, and Class values.'},
{id:4888,topic:'junit',difficulty:'intermediate',question:'In JUnit 5, when are @AfterEach methods guaranteed to run?',options:['Only when the test passes','Only when the test fails','After every test method regardless of outcome, including tests that fail or throw exceptions','Only after tests that complete normally'],answer:2,explanation:'@AfterEach methods are guaranteed to run after every test method regardless of the test outcome (pass, fail, or error). This guarantee ensures cleanup always occurs. Exceptions thrown in @AfterEach are reported but do not prevent other @AfterEach methods from running.'},
{id:4889,topic:'junit',difficulty:'advanced',question:'Can you have multiple @BeforeEach methods in a single JUnit 5 test class?',options:['No, only one is allowed','Yes, and all of them will run before each test in an unspecified order','Yes, they run in declaration order','No, use a single method with multiple calls inside'],answer:1,explanation:'JUnit 5 allows multiple @BeforeEach methods in a test class. All of them run before each test, but the execution order among multiple @BeforeEach methods in the same class is not guaranteed. Use a single @BeforeEach and call helper methods if order matters.'},
{id:4890,topic:'junit',difficulty:'intermediate',question:'What does @DisplayName("🚀 Test name with emoji") demonstrate in JUnit 5?',options:['Emoji cause test failures','Display names support any Unicode character including emoji','Only ASCII characters are supported','Emoji replace tag annotations'],answer:1,explanation:'@DisplayName in JUnit 5 supports any valid Java string, including Unicode characters and emoji. This enables expressive, human-readable test names in test reports and IDEs. The feature is particularly popular in BDD-style test suites for readability.'},
{id:4891,topic:'junit',difficulty:'intermediate',question:'How do you run only tests tagged with "smoke" using Maven Surefire with JUnit 5?',options:['Add -Dgroups=smoke to the Maven command','Use @RunWith(SmokeRunner.class)','Configure <configuration><groups>smoke</groups></configuration> in the Surefire plugin','Tags cannot be used with Maven'],answer:2,explanation:'Maven Surefire plugin 2.22.0+ supports JUnit 5 tags via the <groups> configuration element. You can also use -Dgroups=smoke on the command line. The <excludedGroups> element excludes tags. This replaces JUnit 4\'s @Category filtering.'},
{id:4892,topic:'junit',difficulty:'advanced',question:'In @ParameterizedTest, what is implicit type conversion?',options:['JUnit converts assertion types automatically','JUnit automatically converts String argument values to the declared parameter type using TypedArgumentConverter','Arguments are converted to JSON','It converts test results to strings'],answer:1,explanation:'JUnit 5 performs implicit type conversion for @ParameterizedTest arguments: String values from @ValueSource or @CsvSource are automatically converted to primitive types, enums, dates, UUIDs, and other types using built-in converters, or custom converters via @ConvertWith.'},
{id:4893,topic:'junit',difficulty:'intermediate',question:'What is the purpose of the TestInfo parameter that JUnit 5 can inject into test methods?',options:['It returns the test result','It provides metadata about the current test: display name, tags, test class, and test method','It provides the Assertions instance','It gives access to the JUnit configuration'],answer:1,explanation:'TestInfo is injected by JUnit\'s built-in TestInfoParameterResolver. It provides getDisplayName(), getTags(), getTestClass(), and getTestMethod() to access metadata about the currently running test, useful for conditional logic or logging within tests.'},
{id:4894,topic:'junit',difficulty:'intermediate',question:'What does the @MethodSource value attribute specify when the factory method is in a different class?',options:['The class name only','A fully qualified class name followed by # and the method name','The method name only','A Spring bean name'],answer:1,explanation:'To use a factory method from a different class, specify @MethodSource("com.example.TestDataFactory#provideArguments"). The format is "fully.qualified.ClassName#methodName". If omitted, JUnit looks for a same-name method in the current test class.'},
{id:4895,topic:'junit',difficulty:'advanced',question:'What is the Alphanumeric method orderer in JUnit 5 and why was it deprecated?',options:['It was renamed to DisplayName','MethodOrderer.Alphanumeric ordered by method name and parameter type list and was deprecated in 5.7 in favor of MethodOrderer.MethodName','It was replaced by Random','It was found to be non-deterministic'],answer:1,explanation:'MethodOrderer.Alphanumeric (deprecated in JUnit 5.7) sorted tests alphanumerically by method name and formal parameter type list. It was replaced by MethodOrderer.MethodName which does the same and MethodOrderer.DisplayName for display-name-based ordering.'},
{id:4896,topic:'junit',difficulty:'intermediate',question:'What is the purpose of the TestReporter parameter that JUnit 5 can inject?',options:['It generates HTML test reports','It allows tests to publish key-value pairs as reporting entries that appear in test output','It sends test results to a remote server','It replaces System.out in tests'],answer:1,explanation:'TestReporter is injected by JUnit\'s built-in TestReporterParameterResolver. Its publishEntry(String key, String value) method publishes reporting entries that are included in the test execution output, useful for logging diagnostic information without polluting stdout.'},
{id:4897,topic:'junit',difficulty:'intermediate',question:'In JUnit 5, what determines whether a class is recognized as a test class?',options:['It must extend TestCase','It must be named *Test or Test*','JUnit discovers classes containing @Test methods or annotated with @TestFactory, @TestTemplate, etc. No inheritance required','It must be annotated with @TestClass'],answer:2,explanation:'JUnit 5 uses a TestEngine discovery mechanism. By default, the Jupiter engine finds classes with methods annotated with @Test, @ParameterizedTest, @RepeatedTest, @TestFactory, or @TestTemplate. No inheritance from TestCase is needed—JUnit 5 is completely annotation-driven.'},
{id:4898,topic:'junit',difficulty:'advanced',question:'What is @TestFactory used for in JUnit 5?',options:['Creating mock objects','Generating test cases dynamically at runtime as a Stream or Collection of DynamicTest','Building test data factories','Registering custom argument sources'],answer:1,explanation:'@TestFactory marks a method that returns dynamic tests (DynamicTest, DynamicContainer, or streams/collections thereof). Unlike @Test, these tests are generated programmatically at runtime, enabling truly data-driven test generation beyond what @ParameterizedTest supports.'},
{id:4899,topic:'junit',difficulty:'intermediate',question:'What is the default scope of a @TempDir when applied to an instance field (with default PER_METHOD lifecycle)?',options:['Shared across all tests in the class','Created once per test class instantiation, meaning once per test method','Created once for the entire JVM','Shared only between @BeforeEach and the test'],answer:1,explanation:'With the default PER_METHOD lifecycle, a new test class instance is created for each test. Therefore, an instance @TempDir field gets a fresh temporary directory for each test method, since a new instance (and thus new field injection) occurs per test.'},
{id:4900,topic:'junit',difficulty:'advanced',question:'Which JUnit 5 feature allows you to create a @Test composed with @Tag and @DisplayName in one custom annotation?',options:['@TestTemplate','Composed annotations using meta-annotations','@ExtendWith','@RegisterExtension'],answer:1,explanation:'JUnit 5\'s composed annotation support lets you create a custom annotation like @FastTest, annotate it with @Test, @Tag("fast"), and @DisplayName at the meta level. Tests annotated with @FastTest automatically get all three behaviors, reducing boilerplate.'},
{id:4901,topic:'junit',difficulty:'intermediate',question:'What is the execution guarantee of @AfterAll relative to @AfterEach in JUnit 5?',options:['@AfterAll runs before @AfterEach','@AfterEach runs for each test, then @AfterAll runs once after all tests have completed','They run concurrently','@AfterAll replaces @AfterEach when present'],answer:1,explanation:'@AfterEach runs after each individual test method. @AfterAll runs once after all test methods in the class have been executed (including all their @AfterEach methods). The order is: @BeforeAll → (@BeforeEach → @Test → @AfterEach) × N → @AfterAll.'},
{id:4902,topic:'junit',difficulty:'intermediate',question:'What format do you use to pass a null literal in @CsvSource in JUnit 5?',options:['Leave the field completely empty between commas','Write the word null in single quotes','Configure the nullValues attribute with a sentinel string and use that string','Write NULL in uppercase'],answer:2,explanation:'By default, an empty value in @CsvSource results in an empty string. To pass null, configure the nullValues attribute: @CsvSource(value={"test, NIL"}, nullValues="NIL") and use "NIL" in the CSV data where null is intended.'},
{id:4903,topic:'junit',difficulty:'intermediate',question:'Can @Nested test classes be further nested (multiple levels deep) in JUnit 5?',options:['No, only one level of nesting is supported','Yes, arbitrarily deep nesting is supported','Up to three levels','Only two levels with @Nested applied twice'],answer:1,explanation:'JUnit 5 supports arbitrarily deep @Nested class hierarchies. A @Nested class can itself contain inner @Nested classes. Lifecycle methods from all enclosing classes are invoked from outermost to innermost, providing layered setup and teardown at each nesting level.'},
{id:4904,topic:'junit',difficulty:'advanced',question:'How does JUnit 5 determine the order of @BeforeEach execution when both outer and inner (nested) classes define @BeforeEach?',options:['Inner class @BeforeEach runs first','Outer class @BeforeEach runs first, then inner class @BeforeEach','Order is undefined','They run concurrently'],answer:1,explanation:'JUnit 5 executes lifecycle methods in an outside-in order for setup: the outermost enclosing class\'s @BeforeEach runs first, then each nested level\'s @BeforeEach in order. For teardown (@AfterEach), the order is inside-out.'},
{id:4905,topic:'junit',difficulty:'intermediate',question:'What does the @EnumSource modes attribute MATCH_ANY do?',options:['Includes all enum constants','Includes enum constants whose names match any of the supplied patterns','Excludes all matching constants','Runs the test once for each character in the pattern'],answer:1,explanation:'MATCH_ANY mode in @EnumSource treats the names array as regex patterns and includes any enum constant whose name matches at least one pattern. Other modes are INCLUDE (exact match include), EXCLUDE (exact match exclude), and MATCH_ALL (must match all patterns).'},
{id:4906,topic:'junit',difficulty:'intermediate',question:'What is the execution model for @ParameterizedTest invocations—are they considered separate tests or one test?',options:['One test with multiple assertions','Each invocation is treated as a separate test with its own result','They are run as a single test but failures are collected','They share the same TestInfo instance'],answer:1,explanation:'Each invocation of a @ParameterizedTest is treated as a separate, independently reported test execution. Each gets its own result (pass/fail), its own display name (based on the name pattern), and is individually visible in test reports and IDEs.'},
{id:4907,topic:'junit',difficulty:'advanced',question:'What is the role of the AnnotationConsumerInitializer in JUnit 5 parameterized tests?',options:['It processes @CsvSource annotations','It initializes argument providers or converters that implement AnnotationConsumer, injecting the relevant annotation into them','It validates annotation syntax','It generates display names'],answer:1,explanation:'AnnotationConsumer<A> is an interface that ArgumentsProviders and ArgumentConverters implement to receive the annotation they are associated with. JUnit\'s AnnotationConsumerInitializer calls accept(annotation) on providers/converters that implement this interface, giving them access to their annotation\'s attributes.'},
{id:4908,topic:'junit',difficulty:'intermediate',question:'In JUnit 5, what happens if a @Disabled test class is run?',options:['All tests in the class are skipped','Only static tests are run','The class throws an exception','Tests run but results are ignored'],answer:0,explanation:'When @Disabled is applied to a test class, all test methods within that class are skipped. JUnit reports them as disabled/skipped in the test results. The class-level @Disabled is a blanket disable for all contained tests.'},
{id:4909,topic:'junit',difficulty:'intermediate',question:'What is the argument conversion order JUnit 5 uses for @ParameterizedTest parameters?',options:['Implicit conversion, then @ConvertWith, then ArgumentConverter','@ConvertWith annotation, then explicit ArgumentAggregators, then implicit widening conversion','Widening primitive conversion, then implicit type conversion, then explicit ArgumentConverter','Random ordering decided at runtime'],answer:2,explanation:'JUnit 5 applies argument conversions in order: (1) widening primitive conversion (int to long), (2) implicit type conversion via built-in converters (String to enum, etc.), (3) explicit conversion via @ConvertWith specifying a custom ArgumentConverter implementation.'},
{id:4910,topic:'junit',difficulty:'advanced',question:'What is ArgumentsAccessor in JUnit 5 and when would you use it?',options:['A way to share arguments between test methods','A parameter type that gives access to all arguments of a parameterized test invocation by index and with type conversion','It replaces @CsvSource for complex types','An alternative to TestInfo for parameterized tests'],answer:1,explanation:'ArgumentsAccessor can be declared as a test method parameter in place of individual arguments. It provides get(index, type) methods to retrieve any argument by index with type conversion. Useful when you want to process arguments programmatically without explicit individual parameters.'},
{id:4911,topic:'junit',difficulty:'intermediate',question:'What type does @CsvFileSource\'s resources attribute accept?',options:['A File object','A classpath resource path as a string (e.g., "/data/test.csv")','A URL','A File[] array'],answer:1,explanation:'@CsvFileSource\'s resources attribute accepts one or more classpath resource paths as strings, for example @CsvFileSource(resources = "/test-data.csv"). The files are located on the test classpath. The files attribute accepts file system paths instead.'},
{id:4912,topic:'junit',difficulty:'intermediate',question:'What is the maximum nesting depth recommended for @Nested test classes for maintainability?',options:['1','2-3 levels','No official recommendation, but deeper nesting reduces readability','Exactly 5 levels'],answer:2,explanation:'JUnit 5 supports unlimited nesting levels, but there is no official maximum. In practice, 2-3 levels is the community recommendation for maintainability. Excessive nesting makes tests harder to read and navigate. Use @DisplayName at each level for clarity.'},
{id:4913,topic:'junit',difficulty:'intermediate',question:'In JUnit 5, which assertions method can be used to check iterable equality considering element order?',options:['assertIterableEquals','assertCollectionEquals','assertListEquals','assertOrderedEquals'],answer:0,explanation:'assertIterableEquals(expected, actual) asserts that two iterables are deeply equal, meaning they contain the same elements in the same order. It supports nested iterables and works with any Iterable, including lists, sets (though set order is undefined), and custom iterables.'},
{id:4914,topic:'junit',difficulty:'intermediate',question:'What happens when @TempDir fails to delete a file after a test (e.g., because it is locked)?',options:['JUnit throws an exception and fails the test','JUnit logs a warning but the test result is not affected','JUnit retries deletion 3 times','The test is marked as aborted'],answer:1,explanation:'By default, if JUnit 5 cannot delete a @TempDir directory (e.g., a file is still open), it logs a warning but does not fail the test. The cleanup.mode attribute in JUnit 5.9+ allows configuring behavior (ALWAYS, ON_SUCCESS, NEVER) to control when deletion is attempted.'},
{id:4915,topic:'junit',difficulty:'advanced',question:'What is the purpose of the @TestTemplate annotation in JUnit 5?',options:['A template for copy-pasting test code','An annotation for abstract test methods','Marks a method as a template for multiple invocations driven by registered TestTemplateInvocationContextProviders','Used to generate documentation templates'],answer:2,explanation:'@TestTemplate is a lower-level mechanism than @ParameterizedTest and @RepeatedTest—both are implemented using it. It marks a method as a template that gets invoked for each TestTemplateInvocationContext provided by registered TestTemplateInvocationContextProviders.'},
{id:4916,topic:'junit',difficulty:'intermediate',question:'How do you exclude a specific test tag using Maven Surefire with JUnit 5?',options:['<includeGroups>!slow</includeGroups>','<excludedGroups>slow</excludedGroups>','<tags exclude="slow"/>','@ExcludeTag("slow") on the class'],answer:1,explanation:'Maven Surefire 2.22.0+ supports JUnit 5 tag filtering via <configuration><excludedGroups>slow</excludedGroups></configuration>. This tells the plugin to skip all tests tagged with "slow". The <groups> element specifies tags to include.'},
{id:4917,topic:'junit',difficulty:'intermediate',question:'What is the difference between assertLinesMatch() and assertEquals() for List<String>?',options:['They are identical','assertLinesMatch supports fast-forward markers (>>>N) and regex patterns in expected strings','assertLinesMatch checks byte-level equality','assertEquals supports regex; assertLinesMatch does not'],answer:1,explanation:'assertLinesMatch(expectedLines, actualLines) has special semantics: expected strings starting and ending with >> are regex patterns, and lines starting with ">>>" followed by a number are fast-forward markers that skip N lines. This makes it powerful for matching log output.'},
{id:4918,topic:'junit',difficulty:'advanced',question:'Which SPI mechanism does JUnit 5 use for automatic extension registration?',options:['java.util.ServiceLoader with the org.junit.jupiter.api.extension.Extension interface','java.util.ServiceLoader with TestEngine','Spring\'s @AutoConfiguration','META-INF/extensions.xml'],answer:0,explanation:'JUnit 5 supports automatic extension registration via Java\'s ServiceLoader mechanism. Creating a file META-INF/services/org.junit.jupiter.api.extension.Extension listing your extension class(es) registers them globally without requiring @ExtendWith on every test class.'},
{id:4919,topic:'junit',difficulty:'intermediate',question:'What is the purpose of the junit.jupiter.testinstance.lifecycle.default configuration parameter?',options:['Sets the default timeout for tests','Changes the default test lifecycle from PER_METHOD to PER_CLASS globally','Configures the default display name format','Enables parallel execution'],answer:1,explanation:'Setting junit.jupiter.testinstance.lifecycle.default=per_class in junit-platform.properties changes the default lifecycle for all test classes to PER_CLASS without needing @TestInstance on every class. This means all test classes share a single instance unless overridden.'},
{id:4920,topic:'junit',difficulty:'advanced',question:'What interface does a ParameterizedTest ArgumentsProvider implement, and what method must be overridden?',options:['ArgumentSource; provide()','ArgumentsProvider; provideArguments(ExtensionContext context)','ArgumentFactory; createArguments(Class<?>[] types)','ParameterProvider; getParameters()'],answer:1,explanation:'A custom ArgumentsProvider implements org.junit.jupiter.params.provider.ArgumentsProvider and overrides provideArguments(ExtensionContext context) which returns a Stream<? extends Arguments>. It is registered via @ArgumentsSource(MyProvider.class) on the test method.'},
]);
